package dev.colonyhorizons.remote;

import dev.colonyhorizons.remote.RemoteModels.*;
import dev.colonyhorizons.mayor.*;
import dev.colonyhorizons.supply.*;
import dev.colonyhorizons.integration.ArcologyCatalog;
import com.ldtteam.structurize.storage.StructurePacks;
import com.ldtteam.structurize.api.RotationMirror;
import com.minecolonies.api.colony.IColonyManager;
import com.minecolonies.api.blocks.AbstractBlockHut;
import com.minecolonies.core.tileentities.TileEntityColonyBuilding;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.levelgen.structure.BoundingBox;
import java.util.*;
import java.nio.charset.StandardCharsets;

/** Bounded new buildings, paid through the existing warehouse. Never enlarges the land claim. */
public final class RemoteExpansion {
 private RemoteExpansion(){}
 private static Development owned(ServerPlayer actor,UUID id){var r=RemoteDevelopmentData.get(actor.serverLevel()).find(id).orElseThrow();var c=IColonyManager.getInstance().getColonyByDimension(r.draft().request().colonyId(),actor.level().dimension());if(c==null||!actor.getUUID().equals(r.owner())||!r.owner().equals(c.getPermissions().getOwner()))throw new SecurityException("Only the current owner can expand this outpost");return r;}
 private static void ready(ServerLevel level,Development r){if(r.phase()!=Phase.OPERATING||!MayorService.available(level,r.id())||!MayorLogistics.ready(level,r.id())||!RemoteTickets.snapshot(level).containsKey(r.id()))throw new IllegalArgumentException("Complete and resume the settlement before expanding");}
 public static ExpansionProposal review(ServerPlayer actor,UUID id,String role){
  var l=actor.serverLevel();var r=owned(actor,id);ready(l,r);if(!Set.of("home","lumberjack").contains(role))throw new IllegalArgumentException("Choose a home or forester hut");var data=RemoteDevelopmentData.get(l);
  for(var existing:data.expansions(id).values())if(existing.plan().role().equals(role)&&existing.state()==ExpansionProposal.State.PROPOSED)return existing;
  if(data.expansions(id).values().stream().anyMatch(e->e.approved()&&e.state()!=ExpansionProposal.State.COMPLETE))throw new IllegalArgumentException("Finish the approved expansion first");
  for(int slot=0;slot<3;slot++){var plan=plan(l,r,role,slot);if(data.expansions(id).values().stream().anyMatch(e->e.state()!=ExpansionProposal.State.REJECTED&&e.plan().upgradeVolume().intersects(plan.upgradeVolume())))continue;try{validate(l,r,plan);var old=data.expansions(id).get(plan.operationId());var e=new ExpansionProposal(plan,cost(l,r,plan),ExpansionProposal.State.PROPOSED,old==null?0:ExpansionProposal.renewedRevision(old));data.putExpansion(id,e);data.checkpoint(l);return e;}catch(IllegalArgumentException ignored){/* Try only the three bounded, approved-land positions. */}}
  throw new IllegalArgumentException("No supported, clear expansion space remains inside this outpost");
 }
 public static void decide(ServerPlayer actor,UUID id,UUID operation,long revision,boolean approve){var l=actor.serverLevel();var r=owned(actor,id);ready(l,r);var data=RemoteDevelopmentData.get(l);var e=Optional.ofNullable(data.expansions(id).get(operation)).orElseThrow(()->new IllegalArgumentException("Unknown expansion review"));if(e.revision()!=revision||e.state()!=ExpansionProposal.State.PROPOSED)throw new IllegalArgumentException("Expansion changed; review it again");if(approve){validate(l,r,e.plan());if(!cost(l,r,e.plan()).equals(e.cost()))throw new IllegalArgumentException("Expansion materials changed");if(data.expansions(id).values().stream().anyMatch(p->p.approved()&&p.state()!=ExpansionProposal.State.COMPLETE))throw new IllegalArgumentException("Finish the previous expansion first");}data.decideExpansion(id,r.revision(),e.next(approve?ExpansionProposal.State.APPROVED:ExpansionProposal.State.REJECTED));data.checkpoint(l);}
 private static BuildingPlan plan(ServerLevel l,Development r,String role,int slot){
  String name=r.draft().buildings().getFirst().pack(),path="fundamentals/"+(role.equals("home")?"citizen":"lumberjack");var pack=StructurePacks.getStructurePack(name);if(pack==null)throw new IllegalArgumentException("Style pack unavailable");var catalog=ArcologyCatalog.inspect(pack.getPath(),l.registryAccess());if(catalog.entries().size()!=25||catalog.diagnostics().stream().anyMatch(s->!s.startsWith("Missing optional route terminal")))throw new IllegalArgumentException("Style pack changed");
  var base=catalog.entries().stream().filter(e->e.relativePath().equals(path+"1.blueprint")).findFirst().orElseThrow();var anchor=r.draft().request().center().offset((slot-1)*24,base.anchor().getY(),-44);BoundingBox box=null;var hashes=new StringBuilder();
  for(int level=1;level<=r.draft().request().maxBuildingLevel();level++){String p=path+level+".blueprint";var b=catalog.entries().stream().filter(e->e.relativePath().equals(p)).findFirst().orElseThrow();var origin=anchor.subtract(b.anchor());var v=new BoundingBox(origin.getX(),origin.getY(),origin.getZ(),origin.getX()+b.size().getX()-1,origin.getY()+b.size().getY()-1,origin.getZ()+b.size().getZ()-1);if(box==null)box=v;else box.encapsulate(v);hashes.append(p).append(':').append(b.sha256()).append(';');}
  return new BuildingPlan(UUID.nameUUIDFromBytes((r.id()+":expansion:"+slot).getBytes(StandardCharsets.UTF_8)),role,anchor,name,path+"1.blueprint",ArcologySettlementLayout.sha(hashes.toString()),RotationMirror.NONE,box,1);
 }
 private static Map<ItemKey,Integer> anchorCost(ServerLevel l,Development r,BuildingPlan p){var bp=StructurePacks.getBlueprint(p.pack(),p.blueprint(),l.registryAccess());var block=bp.getBlockState(bp.getPrimaryBlockOffset()).getBlock();if(!(block instanceof AbstractBlockHut<?>))throw new IllegalArgumentException("Missing native hut");int dirt=p.anchor().getY()-r.draft().request().center().getY();if(dirt<0||dirt>1)throw new IllegalArgumentException("Unsupported hut height");var result=new HashMap<ItemKey,Integer>();result.put(new ItemKey(new ItemStack(block)),1);if(dirt>0)result.put(new ItemKey(new ItemStack(Items.DIRT)),dirt);return Map.copyOf(result);}
 private static Map<ItemKey,Integer> cost(ServerLevel l,Development r,BuildingPlan p){var result=new HashMap<>(MayorUpgrades.bill(l,p,p.blueprint()));anchorCost(l,r,p).forEach((k,n)->result.merge(k,n,Math::addExact));return Map.copyOf(result);}
 private static void validate(ServerLevel l,Development r,BuildingPlan p){
  FoundingPlacement.validatePack(l,r);boolean matches=false;for(int slot=0;slot<3;slot++)if(plan(l,r,p.role(),slot).equals(p)){matches=true;break;}if(!matches)throw new IllegalArgumentException("Expansion blueprint changed");var data=RemoteDevelopmentData.get(l);var c=IColonyManager.getInstance().getColonyByDimension(r.draft().request().colonyId(),l.dimension());
  for(var old:data.buildings(r.id()))if(!old.operationId().equals(p.operationId())&&old.upgradeVolume().intersects(p.upgradeVolume()))throw new IllegalArgumentException("Expansion overlaps a building");var v=p.upgradeVolume();if(!RemoteModels.contains(r.draft().request().allowedArea(),v))throw new IllegalArgumentException("Expansion exceeds approved area");
  for(var pos:BlockPos.betweenClosed(v.minX(),v.minY(),v.minZ(),v.maxX(),v.maxY(),v.maxZ())){var chunk=new ChunkPos(pos);if(!l.hasChunkAt(pos)||!l.getWorldBorder().isWithinBounds(pos)||!data.confirmedClaims(r.id()).contains(chunk))throw new IllegalArgumentException("Expansion land unavailable");var claim=IColonyManager.getInstance().getClaimData(l.dimension(),chunk);if(claim==null||claim.getOwningColony()!=c.getID())throw new IllegalArgumentException("Expansion ownership changed");if(l.getBlockEntity(pos)!=null||!l.getFluidState(pos).isEmpty()||!l.getBlockState(pos).getCollisionShape(l,pos).isEmpty())throw new IllegalArgumentException("Expansion area is obstructed");if(pos.getY()==v.minY()&&(!l.getFluidState(pos.below()).isEmpty()||!l.getBlockState(pos.below()).isFaceSturdy(l,pos.below(),Direction.UP)))throw new IllegalArgumentException("Expansion ground is unsupported");}
  var bp=StructurePacks.getBlueprint(p.pack(),p.blueprint(),l.registryAccess());var hut=(AbstractBlockHut<?>)bp.getBlockState(bp.getPrimaryBlockOffset()).getBlock();var actor=l.getServer().getPlayerList().getPlayer(r.owner());if(actor==null||!c.getPermissions().hasPermission(actor,com.minecolonies.api.colony.permissions.Action.PLACE_HUTS)||!c.getServerBuildingManager().canPlaceAt(hut,p.anchor(),actor))throw new IllegalArgumentException("Native hut placement is unavailable");var effect=c.getResearchManager().getResearchEffectIdFrom(hut);if(com.minecolonies.api.IMinecoloniesAPI.getInstance().getGlobalResearchTree().getResearchForEffect(effect)!=null&&c.getResearchManager().getResearchEffects().getEffectStrength(effect)<=0)throw new IllegalArgumentException("Unlock the native hut research first");
 }
 public static StepResult tick(ServerLevel l,UUID id){var data=RemoteDevelopmentData.get(l);var r=data.find(id).orElseThrow();if(!Set.of(Phase.BUILDING,Phase.OPERATING).contains(r.phase()))return idle();var actor=l.getServer().getPlayerList().getPlayer(r.owner());if(actor==null||!MayorService.available(l,id)||!MayorLogistics.ready(l,id)||!RemoteTickets.snapshot(l).containsKey(id))return idle();
  for(var e:data.expansions(id).values())if(e.approved()&&e.state()!=ExpansionProposal.State.COMPLETE){try{
   owned(actor,id);if(e.state()==ExpansionProposal.State.PLACING)return blocked("Interrupted hut payment requires recovery; no replay");
   if(e.state()==ExpansionProposal.State.PLACED){if(data.construction(id).values().stream().anyMatch(c->c.building().equals(e.plan().operationId())&&c.target()==1&&c.state()==ConstructionJournal.State.COMPLETE)){data.putExpansion(id,e.next(ExpansionProposal.State.COMPLETE));data.checkpoint(l);return new StepResult("Expansion complete",List.of(),true);}return idle();}
   validate(l,r,e.plan());if(!cost(l,r,e.plan()).equals(e.cost()))return blocked("Expansion materials changed; preserve the review");
   var warehouse=MayorLogistics.warehouse(l,id).orElseThrow();var view=WarehouseInventory.resolve(l,warehouse.getTileEntity());var materials=anchorCost(l,r,e.plan());
   for(var item:materials.entrySet())if(count(view.inventory(),item.getKey())<item.getValue()){var op=UUID.nameUUIDFromBytes((e.plan().operationId()+":anchor:"+item.getKey().stack().save(l.registryAccess())).getBytes(StandardCharsets.UTF_8));return MayorSupplyController.ensure(l,id,op,warehouse.getPosition(),item.getKey().stack(),item.getValue());}
   // Durable intent precedes extraction. A crash here is quarantined, never automatically replayed.
   view.validate(l);data.putExpansion(id,e.next(ExpansionProposal.State.PLACING));data.checkpoint(l);
   try{for(var item:materials.entrySet()){int remaining=item.getValue();for(int slot=0;slot<view.inventory().getSlots()&&remaining>0;slot++){var stack=view.inventory().getStackInSlot(slot);if(ItemStack.isSameItemSameComponents(stack,item.getKey().stack())){int take=Math.min(stack.getCount(),remaining);var extracted=view.inventory().extractItem(slot,take,false);if(extracted.getCount()!=take||!ItemStack.isSameItemSameComponents(extracted,item.getKey().stack()))throw new IllegalStateException("Expansion payment changed");remaining-=take;}}if(remaining!=0)throw new IllegalStateException("Expansion payment incomplete");}
    view.entities().forEach(net.minecraft.world.level.block.entity.BlockEntity::setChanged);NativeSupplyCheckpoint.flushAndVerify(l,view.entities());
    var p=e.plan();var bp=StructurePacks.getBlueprint(p.pack(),p.blueprint(),l.registryAccess());var state=bp.getBlockState(bp.getPrimaryBlockOffset());var hutBlock=(AbstractBlockHut<?>)state.getBlock();for(int y=r.draft().request().center().getY();y<p.anchor().getY();y++)if(!l.setBlockAndUpdate(new BlockPos(p.anchor().getX(),y,p.anchor().getZ()),Blocks.DIRT.defaultBlockState()))throw new IllegalStateException("Support placement failed");if(!l.setBlockAndUpdate(p.anchor(),state))throw new IllegalStateException("Hut placement failed");hutBlock.onBlockPlacedByBuildTool(l,p.anchor(),state,actor,new ItemStack(hutBlock),p.transform(),p.pack(),p.blueprint());var c=warehouse.getColony();var b=c.getServerBuildingManager().getBuilding(p.anchor());if(b==null||b.getBuildingLevel()!=0||!(l.getBlockEntity(p.anchor()) instanceof TileEntityColonyBuilding hut))throw new IllegalStateException("Unfinished native hut registration failed");hut.getPersistentData().putUUID("colonyhorizons:founding_anchor",p.operationId());hut.setChanged();NativeSupplyCheckpoint.flushAndVerify(l,List.of(hut));NativeFoundingCheckpoint.save(l,c);data.putExpansion(id,data.expansions(id).get(p.operationId()).next(ExpansionProposal.State.PLACED));data.checkpoint(l);return new StepResult("Paid expansion hut placed",List.of(),true);
   }catch(RuntimeException failure){var current=data.find(id).orElseThrow();data.transition(id,current.revision(),Phase.RECOVERY_NEEDED);data.checkpoint(l);throw failure;}
  }catch(IllegalArgumentException|IllegalStateException failure){return blocked(failure.getMessage()==null?"Expansion needs review":failure.getMessage());}}
  return idle();
 }
 private static int count(net.neoforged.neoforge.items.IItemHandler inventory,ItemKey item){int n=0;for(int slot=0;slot<inventory.getSlots();slot++)if(ItemStack.isSameItemSameComponents(inventory.getStackInSlot(slot),item.stack()))n+=inventory.getStackInSlot(slot).getCount();return n;}
 private static StepResult idle(){return new StepResult("No expansion action",List.of(),false);}
 private static StepResult blocked(String reason){return new StepResult("Expansion waiting",List.of(reason),false);}
}
